<?php
$isNew=isset($_GET['new']);$editorRows=$isNew?array_fill(0,3,[]):$formRows;$editorHead=$isNew?[]:$head;$editorDetails=$isNew?[]:$details;
$editorColumns=form_columns($formType);
$editorItemLabels=match($formType){
  'RIS'=>['Stock No.','Unit','Description','Requisition / Issue Quantity','Stock Available / Remarks'],
  'Stock Card'=>['Reference','Unit','Description','Receipt Quantity','Issue / Balance / Days to Consume'],
  'Supply Ledger Card'=>['Reference','Unit','Description','Quantity','Receipt / Issue / Balance Costs'],
  'RSMI'=>['Stock No.','Unit','Item','Quantity Issued','Unit Cost / Amount'],
  'Waste Materials Report'=>['Item','Unit','Description','Quantity','Official Receipt No. / Date / Amount'],
  'RPCI'=>['Stock Number','Unit of Measure','Article / Description','On Hand Quantity','Unit Value / Balance / Shortage / Overage / Remarks'],
  default=>['Reference','Unit','Description','Quantity','Remarks']
};
